// All numbers below are teaching assumptions, independent of provincial tariffs.
const AnimationModel={
 energy(power=2,hours=3,price=300){const energy=power*hours;return {power,hours,price,energy,kwh:energy*1000,cost:energy*price}},
 dispatch(demand){let remaining=demand;const quantities=[80,100,120].map(cap=>{const q=Math.min(cap,Math.max(0,remaining));remaining-=q;return q});return {demand,quantities,shortfall:Math.max(0,remaining),price:remaining>0?null:demand<=80?180:demand<=180?300:480}},
 settlement(actual){const plan=100,daPrice=300,rtPrice=450,delta=actual-plan;return {plan,actual,delta,da:plan*daPrice,rt:delta*rtPrice,total:plan*daPrice+delta*rtPrice}},
 storage(efficiency=.88,avoidedPrice=.8){const input=100,output=input*efficiency,loss=input-output,cost=input*.3,value=output*avoidedPrice;return {input,output,loss,cost,value,gross:value-cost,efficiency,avoidedPrice}}
};
const animationDefinitions={
 energy:{title:'动画：功率不变，电量怎样累积？',prompt:'先预测：运行时间翻倍，电量会变成几倍？',steps:['认清功率','让时间推进','换算电量单位','计算电能量费用'],boundary:'恒定功率教学算例；价格为演示假设，只计算电能量费用。'},
 dispatch:{title:'动画：谁决定出清价格？',prompt:'先预测：需求从 150 增至 220 MW，是否需要调用 C？',steps:['按报价排序','展示 A 的出力','展示 B 的出力','展示 C 的出力','确定边际价格'],boundary:'单节点、统一边际价格教学模型，忽略网络与复杂机组约束。动画顺序是讲解顺序，不是机组实际依次启动的时间。'},
 settlement:{title:'动画：计划与偏差分开计价',prompt:'先预测：实际用电少于日前安排，偏差电量是什么符号？',steps:['日前安排','实际用电','求偏差电量','合并两部分费用'],boundary:'用电侧两结算简化模型，不代表各省零售用户的完整结算规则。'},
 storage:{title:'动画：100 度电经过储能，还剩多少？',prompt:'先预测：有损耗时，是否能把充入的电全部放出来？',steps:['从电网充入','核对往返损耗','计算替代购电价值','扣除充电成本'],boundary:'用户侧储能替代本地购电的教学算例；运行毛收益未扣投资、运维、税费、融资和更换成本。未模拟真实调度或电池 SOC。'}
};
const animationKinds={0:'energy',4:'dispatch',6:'dispatch',7:'settlement',12:'storage'};
let animationCleanups=[];
function disposeLessonAnimations(){for(const cleanup of animationCleanups)cleanup();animationCleanups=[]}
function lessonAnimation(id){const kind=animationKinds[id];if(!kind)return '';const def=animationDefinitions[kind],uid='anim-'+id;return `<section class="lesson-animation" data-animation="${kind}" aria-label="${def.title}"><div class="animation-title"><span class="tag">交互动画 · 演示假设</span><h3>${def.title}</h3><p>${def.prompt}</p></div><div class="animation-settings">${kind==='dispatch'?`<label for="${uid}-demand">需求功率<select id="${uid}-demand" data-parameter="demand"><option value="150">150 MW</option><option value="220">220 MW</option><option value="320">320 MW · 供给不足</option></select></label>`:kind==='settlement'?`<label for="${uid}-actual">实际用电量<select id="${uid}-actual" data-parameter="actual"><option value="110">110 MWh · 正偏差</option><option value="90">90 MWh · 负偏差</option></select></label>`:kind==='storage'?`<label for="${uid}-eff">往返效率<select id="${uid}-eff" data-parameter="efficiency"><option value="0.88">88% · 演示</option><option value="1">100% · 理想对比</option></select></label><label for="${uid}-price">替代购电单价<select id="${uid}-price" data-parameter="avoidedPrice"><option value="0.8">0.80 元/kWh</option><option value="0.4">0.40 元/kWh</option></select></label>`:'<p>固定功率 2 MW · 运行 3 小时 · 演示价格 300 元/MWh</p>'}</div><div class="animation-scene"></div><div class="animation-reading"></div><p class="animation-explanation" role="status" aria-live="polite"></p><progress class="animation-progress" max="1" value="0" aria-label="本步播放进度"></progress><div class="animation-controls"><button class="primary dark" data-action="play">播放</button><button class="secondary" data-action="previous" aria-label="上一个动画步骤">上一步</button><button class="secondary" data-action="next" aria-label="下一个动画步骤">下一步</button><button class="secondary" data-action="reset">重置</button><span class="animation-step-label"></span></div><label class="animation-scrubber" for="${uid}-step">逐步查看<input id="${uid}-step" class="animation-step-range" type="range" min="0" max="${def.steps.length-1}" value="0" step="1"></label><p class="animation-motion-note"></p><p class="animation-boundary">${def.boundary}</p></section>`}
function animationNumber(n){return Number(n.toFixed(2)).toLocaleString('zh-CN',{maximumFractionDigits:2})}
function animationSVG(content,label,compact,height=240){return `<svg class="anim-desktop" viewBox="0 0 520 240" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg">${content}</svg><svg class="anim-mobile" viewBox="0 0 340 ${height}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg">${compact}</svg>`}
function animationMobileRow(y,label,detail,fraction,footer='',trackFraction=1){return `<text x="12" y="${y}" class="anim-svg-label">${label}</text><text x="328" y="${y}" text-anchor="end" class="anim-svg-detail">${detail}</text><rect x="12" y="${y+15}" width="${316*trackFraction}" height="24" rx="5" class="anim-track"/><rect x="12" y="${y+15}" width="${316*Math.max(0,Math.min(trackFraction,fraction))}" height="24" rx="5" class="anim-fill"/>${footer?`<text x="12" y="${y+65}" class="anim-svg-detail">${footer}</text>`:''}`}
function animationRow(y,label,detail,width,maxWidth=310){return `<text x="18" y="${y+4}" class="anim-svg-label">${label}</text><rect x="170" y="${y-18}" width="${maxWidth}" height="28" rx="5" class="anim-track"/><rect x="170" y="${y-18}" width="${Math.max(0,Math.min(maxWidth,width))}" height="28" rx="5" class="anim-fill"/><text x="18" y="${y+26}" class="anim-svg-detail">${detail}</text>`}
function animationFrame(kind,params,step,progress){const f=animationNumber,r=Math.max(0,Math.min(1,progress));let svg='',values=[],explain='';
 if(kind==='energy'){
  const d=AnimationModel.energy(),fraction=step===0?0:step===1?r:1,h=d.hours*fraction,q=d.energy*fraction;
  svg=animationSVG(animationRow(44,'固定功率',`${d.power} MW`,310)+animationRow(110,'累计时间',`${f(h)} 小时`,310*fraction)+animationRow(176,'累计电量',`${f(q)} MWh`,310*fraction),`固定功率 2 MW，累计 ${f(h)} 小时，对应 ${f(q)} MWh`,animationMobileRow(24,'固定功率',`${d.power} MW`,1)+animationMobileRow(102,'累计时间',`${f(h)} 小时`,fraction)+animationMobileRow(180,'累计电量',`${f(q)} MWh`,fraction));
  values=[['功率',`${d.power} MW`],['运行时间',`${f(h)} h`],['电量',`${f(q)} MWh`]];
  explain=[`功率描述用电或发电的速度，此处保持 ${d.power} MW。`,`功率保持 2 MW，时间增加时电量同步累积。图中的实时数字对应电量 = 功率 × 时间。`,`运行结束：${d.energy} MWh = ${d.kwh.toLocaleString()} kWh。功率单位与电量单位不能混用。`,`费用 = ${d.energy} MWh × ${d.price} 元/MWh = ${d.cost.toLocaleString()} 元。`][step];
 }else if(kind==='dispatch'){
  const d=AnimationModel.dispatch(params.demand),caps=[80,100,120],offers=[180,300,480];
  const shown=d.quantities.map((q,i)=>step<i+1?0:step===i+1?q*r:q);
  const bars=caps.map((cap,i)=>{const y=50+i*62,w=cap/120*280;return `<text x="18" y="${y}" class="anim-svg-label">机组 ${'ABC'[i]}</text><text x="18" y="${y+21}" class="anim-svg-detail">${cap} MW · ${offers[i]} 元/MWh</text><rect x="205" y="${y-19}" width="${w}" height="29" rx="5" class="anim-track"/><rect x="205" y="${y-19}" width="${shown[i]/120*280}" height="29" rx="5" class="anim-fill"/><text x="205" y="${y+31}" class="anim-svg-detail">${step>=i+1?f(shown[i])+' MW（展示出力）':'待展示'}</text>`}).join('');
  const compact=caps.map((cap,i)=>animationMobileRow(24+i*84,`机组 ${'ABC'[i]}`,`${cap} MW · ${offers[i]} 元/MWh`,shown[i]/120,step>=i+1?`${f(shown[i])} MW（展示出力）`:'待展示',cap/120)).join('');
  svg=animationSVG(bars,`需求 ${d.demand} MW；最终 A ${d.quantities[0]}、B ${d.quantities[1]}、C ${d.quantities[2]} MW`,compact,270);
  values=[['需求',`${d.demand} MW`],['总可用供给','300 MW'],['出清价格',step===4?(d.price===null?'不输出价格':d.price+' 元/MWh'):'待确定']];
  explain=step===0?'先按报价从低到高排序：A → B → C。灰条是容量，彩色条是本例选取出力。':step===4?(d.shortfall?`需求超过供给，缺额 ${d.shortfall} MW。模型未设置稀缺定价，不凭空给出价格。`:`最终出力 A ${d.quantities[0]} + B ${d.quantities[1]} + C ${d.quantities[2]} = ${d.demand} MW。边际机组 ${d.demand<=80?'A':d.demand<=180?'B':'C'} 形成 ${d.price} 元/MWh 的统一价格。`):`正在展示机组 ${'ABC'[step-1]} 的选取结果：${d.quantities[step-1]} MW。条形展开只是讲解过程，未展示完成的数值不是新的交易结果。`;
 }else if(kind==='settlement'){
  const d=AnimationModel.settlement(params.actual);
  const deviation=step>=2?`偏差 = ${d.actual} − 100 = ${d.delta>0?'+':''}${d.delta} MWh`:'偏差：实际减去日前安排';
  svg=animationSVG(animationRow(48,'日前安排','100 MWh × 300 元/MWh',280)+animationRow(116,'实际用电',step>=1?`${d.actual} MWh`:'待展示',step>=1?d.actual/110*308*(step===1?r:1):0)+`<text x="18" y="202" class="anim-svg-label">${deviation}</text>`, `日前 100 MWh，实际 ${d.actual} MWh，偏差 ${d.delta} MWh`,animationMobileRow(24,'日前安排','100 MWh',100/110)+animationMobileRow(102,'实际用电',step>=1?`${d.actual} MWh`:'待展示',step>=1?d.actual/110*(step===1?r:1):0)+`<text x="12" y="202" class="anim-svg-label">${deviation}</text>`);
  values=[['日前部分',`${f(d.da)} 元`],['实时部分',step>=2?`${f(d.rt)} 元`:'待计算'],['总成本',step===3?`${f(d.total)} 元`:'待合并']];
  explain=[`日前部分 = 100 × 300 = ${f(d.da)} 元。`,`现在看实际用电：${d.actual} MWh。实际与计划不是同一个量。`,`偏差 = ${d.actual} − 100 = ${d.delta} MWh；实时部分 = ${d.delta} × 450 = ${f(d.rt)} 元。负偏差是差额结算方向，不是负的用电量。`,`总成本 = ${f(d.da)} + (${f(d.rt)}) = ${f(d.total)} 元。`][step];
 }else{
  const d=AnimationModel.storage(params.efficiency,params.avoidedPrice),show=step>=1;
  const compact=`<text x="12" y="24" class="anim-svg-label">充入 ${d.input} kWh</text><text x="12" y="50" class="anim-svg-detail">完成一次往返过程</text><rect x="12" y="70" width="316" height="32" rx="6" class="anim-track"/><rect x="12" y="70" width="${show?316*d.efficiency:316*r}" height="32" rx="6" class="anim-fill"/>${show?`<rect x="${12+316*d.efficiency}" y="70" width="${316*(1-d.efficiency)}" height="32" class="anim-loss"/>`:''}<text x="12" y="136" class="anim-svg-label">${show?`可放出 ${f(d.output)} kWh`:'正在展示充入电量'}</text><text x="12" y="166" class="anim-svg-detail">${show?`损耗 ${f(d.loss)} kWh；${f(d.output)} + ${f(d.loss)} = 100 kWh`:'先记录充入的电量，再展示损耗'}</text><text x="12" y="198" class="anim-svg-detail">${show?'绿色：可放出 · 橙色：损耗':'绿色：充入电量'}</text>`;
  svg=animationSVG(`<text x="18" y="34" class="anim-svg-label">充入 ${d.input} kWh → 完成一次往返过程</text><rect x="18" y="62" width="484" height="42" rx="7" class="anim-track"/><rect x="18" y="62" width="${show?484*d.efficiency:484*r}" height="42" rx="7" class="anim-fill"/>${show?`<rect x="${18+484*d.efficiency}" y="62" width="${484*(1-d.efficiency)}" height="42" class="anim-loss"/>`:''}<text x="18" y="140" class="anim-svg-label">${show?`可放出 ${f(d.output)} kWh`:'正在展示充入电量'}</text><text x="18" y="175" class="anim-svg-detail">${show?`往返损耗 ${f(d.loss)} kWh；${f(d.output)} + ${f(d.loss)} = 100 kWh`:'绿色与损耗部分共同对应 100 kWh 的能量账本'}</text><text x="18" y="211" class="anim-svg-detail">${show?'绿色：可放出电量 · 橙色：往返损耗':'绿色：充入电量（尚未展示往返损耗）'}</text>`, `充入 100 kWh，效率 ${f(d.efficiency*100)}%，可放出 ${f(d.output)}，损耗 ${f(d.loss)} kWh`,compact);
  values=[['充电成本',`${f(d.cost)} 元`],['替代购电价值',step>=2?`${f(d.value)} 元`:'待计算'],['运行毛收益',step>=3?`${f(d.gross)} 元`:'待计算']];
  explain=[`从电网充入 100 kWh，购电单价 0.30 元/kWh，充电成本为 ${f(d.cost)} 元。`,`往返效率 ${f(d.efficiency*100)}%：100 × ${d.efficiency} = ${f(d.output)} kWh，损耗 ${f(d.loss)} kWh。100% 仅为理想对比。`,`放电替代本地购电的价值 = ${f(d.output)} × ${params.avoidedPrice.toFixed(2)} = ${f(d.value)} 元，不是向电网售电的收入。`,`运行毛收益 = ${f(d.value)} − ${f(d.cost)} = ${f(d.gross)} 元。这还不是项目净利润。`][step];
 }
 return {svg,values,explain};
}
function mountLessonAnimations(scope){for(const element of scope.querySelectorAll('[data-animation]')){
 const kind=element.dataset.animation,def=animationDefinitions[kind],scene=element.querySelector('.animation-scene'),reading=element.querySelector('.animation-reading'),explanation=element.querySelector('.animation-explanation'),label=element.querySelector('.animation-step-label'),play=element.querySelector('[data-action=play]'),slider=element.querySelector('.animation-step-range'),media=window.matchMedia('(prefers-reduced-motion: reduce)');
 let step=0,progress=0,playing=false,raf=0,last=0,accumulated=0,lastDraw=0,disposed=false;
 const duration=3200;
 function parameters(){const get=(name,allowed,fallback)=>{const value=Number(element.querySelector(`[data-parameter=${name}]`)?.value);return allowed.includes(value)?value:fallback};return {demand:get('demand',[150,220,320],150),actual:get('actual',[90,110],110),efficiency:get('efficiency',[.88,1],.88),avoidedPrice:get('avoidedPrice',[.4,.8],.8)}}
 function paint(announce=true){if(disposed)return;const frame=animationFrame(kind,parameters(),step,media.matches?1:progress);element.querySelector('.animation-progress').value=media.matches?1:progress;scene.innerHTML=frame.svg;reading.innerHTML=frame.values.map(([t,v])=>`<div><span>${t}</span><strong>${v}</strong></div>`).join('');if(announce)explanation.textContent=frame.explain;label.textContent=`${step+1} / ${def.steps.length} · ${def.steps[step]}`;slider.value=step;slider.setAttribute('aria-valuetext',`${step+1} / ${def.steps.length}，${def.steps[step]}`);element.querySelector('[data-action=previous]').disabled=step===0;element.querySelector('[data-action=next]').disabled=step===def.steps.length-1;play.textContent=playing?'暂停':step===def.steps.length-1&&progress===1?'重播':accumulated?'继续播放':'播放';play.disabled=media.matches;element.querySelector('.animation-motion-note').textContent=media.matches?'已启用减少动态效果。使用上一步、下一步逐步查看，无需播放。':'默认不自动播放；也可以用滑块逐步查看。';}
 function stop(){playing=false;cancelAnimationFrame(raf);raf=0;last=0}
 function tick(now){if(!playing||disposed)return;if(last)accumulated+=Math.min(100,now-last);last=now;const old=step;step=Math.min(def.steps.length-1,Math.floor(accumulated/duration));progress=Math.min(1,(accumulated-step*duration)/duration);if(now-lastDraw>=33||old!==step){paint(old!==step);lastDraw=now}if(accumulated>=duration*def.steps.length){progress=1;stop();paint();return}raf=requestAnimationFrame(tick)}
 play.onclick=()=>{if(playing){stop();paint();return}if(media.matches)return;if(step===def.steps.length-1&&progress===1){step=0;progress=0;accumulated=0}playing=true;last=0;paint();raf=requestAnimationFrame(tick)};
 function jump(n){stop();step=Math.max(0,Math.min(def.steps.length-1,n));progress=1;accumulated=(step+1)*duration;paint()}
 element.querySelector('[data-action=previous]').onclick=()=>jump(step-1);element.querySelector('[data-action=next]').onclick=()=>jump(step+1);element.querySelector('[data-action=reset]').onclick=()=>{stop();step=0;progress=0;accumulated=0;paint()};slider.oninput=()=>jump(Number(slider.value));
 element.querySelectorAll('[data-parameter]').forEach(select=>select.onchange=()=>{stop();step=0;progress=0;accumulated=0;paint()});
 const changed=()=>{stop();paint()},hidden=()=>{if(document.hidden){stop();paint()}};if(media.addEventListener)media.addEventListener('change',changed);else media.addListener(changed);document.addEventListener('visibilitychange',hidden);
 const cleanup=()=>{disposed=true;stop();if(media.removeEventListener)media.removeEventListener('change',changed);else media.removeListener(changed);document.removeEventListener('visibilitychange',hidden)};animationCleanups.push(cleanup);paint();
 }}
document.getElementById('lessonDialog')?.addEventListener('close',disposeLessonAnimations);
document.getElementById('lessonDialog')?.addEventListener('cancel',disposeLessonAnimations);

window.addEventListener('hashchange',()=>{disposeLessonAnimations();const dialog=document.getElementById('lessonDialog');if(dialog?.open)dialog.close()});
